package com.company.notification;

import com.company.notification.model.*;
import com.company.notification.service.NotificationFilterService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static org.assertj.core.api.Assertions.assertThat;

public class NotificationFilterServiceTest {
    private Instant baseTime;
    private Clock clock;
    private NotificationFilterService service;

    @BeforeEach
    void setUp() {
        baseTime = Instant.parse("2026-09-01T12:00:00Z");
        clock = Clock.fixed(baseTime, ZoneId.of("UTC"));
        service = new NotificationFilterService(clock);
    }

    @Test
    void testBlocksBlacklistedSender() {
        var prefs = new UserPreferences("u1", Set.of(Channel.EMAIL), Set.of(NotificationType.PROMO), Set.of("spammer"));
        var notif = new Notification("n1", "u1", "spammer", Channel.EMAIL, NotificationType.PROMO, "hash1", baseTime);
        var result = service.filterNotifications(List.of(notif), Map.of("u1", prefs));
        assertThat(result).isEmpty();
    }

    @Test
    void testDeduplicatesWithin24Hours() {
        var prefs = new UserPreferences("u1", Set.of(Channel.EMAIL), Set.of(NotificationType.TRANSACTION), Set.of());
        var notif1 = new Notification("n1", "u1", "bank", Channel.EMAIL, NotificationType.TRANSACTION, "hash1", baseTime);
        var notif2 = new Notification("n2", "u1", "bank", Channel.EMAIL, NotificationType.TRANSACTION, "hash1", baseTime.plus(Duration.ofHours(2)));

        var batch1 = service.filterNotifications(List.of(notif1), Map.of("u1", prefs));
        assertThat(batch1).hasSize(1);

        var batch2 = service.filterNotifications(List.of(notif2), Map.of("u1", prefs));
        assertThat(batch2).isEmpty();
    }
}

