    }

    @ParameterizedTest
    @ValueSource(strings = {
        "CH9300762011623852957",
        "DE89370400440532013000",
        "GB29NWBK60161331926819",
        "FR1420041010050500013M02606"
    })
    void shouldValidateValidIbans(String validIban) {
