        "INVALID_IBAN",
        "",
        "DE00000000000000000000"
    })
    void shouldRejectInvalidIbans(String invalidIban) {
        assertThat(validator.validate(invalidIban)).isFalse();
    }

    @Test
    void shouldHandleNullGracefully() {
        assertThat(validator.validate(null)).isFalse();
    }
