package com.bank.vector;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

public class SparseVectorTest {

    @Test
    void shouldComputeDotProductCorrectly() {
        int[] nums1 = new int[]{1, 0, 0, 2, 3};
        int[] nums2 = new int[]{0, 3, 0, 4, 0};
        SparseVector v1 = new SparseVector(nums1);
        SparseVector v2 = new SparseVector(nums2);
        // 1*0 + 0*3 + 0*0 + 2*4 + 3*0 = 8
        assertThat(v1.dotProduct(v2)).isEqualTo(8);
    }

    @Test
    void shouldReturnZeroForOrthogonalVectors() {
        int[] nums1 = new int[]{0, 1, 0, 0};
        int[] nums2 = new int[]{1, 0, 0, 0};
        SparseVector v1 = new SparseVector(nums1);
        SparseVector v2 = new SparseVector(nums2);
        assertThat(v1.dotProduct(v2)).isEqualTo(0);
    }

    @Test
    void shouldHandleEmptyAndZeroVectors() {
        SparseVector v1 = new SparseVector(new int[]{0, 0, 0});
        SparseVector v2 = new SparseVector(new int[]{0, 0, 0});
        assertThat(v1.dotProduct(v2)).isEqualTo(0);
    }
}

